"""Closest Leaf in a BST — parent links turn the tree into a graph, then BFS.

Time: O(n)   Space: O(n)
"""
from collections import deque

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def closestLeaf(self, root, k: int) -> int:
        parents = {}
        start = None

        def link(node, parent) -> None:
            nonlocal start
            if not node:
                return
            parents[node] = parent
            if node.val == k:
                start = node
            link(node.left, node)
            link(node.right, node)

        link(root, None)

        seen = {start}
        queue = deque([start])
        while queue:
            best = None
            for _ in range(len(queue)):
                node = queue.popleft()
                if not node.left and not node.right:
                    best = node.val if best is None else min(best, node.val)
                for nxt in (node.left, node.right, parents[node]):
                    if nxt and nxt not in seen:
                        seen.add(nxt)
                        queue.append(nxt)
            if best is not None:
                return best             # ties inside a level go to the smallest
        return -1
